CREATE TABLE IF NOT EXISTS businesses(id text PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,color text NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text NOT NULL UNIQUE,password text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(user_id text NOT NULL REFERENCES users(id),business_id text NOT NULL REFERENCES businesses(id),role text NOT NULL,PRIMARY KEY(user_id,business_id));
CREATE TABLE IF NOT EXISTS sessions(hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires integer NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(email text PRIMARY KEY,count integer NOT NULL,reset integer NOT NULL);
CREATE TABLE IF NOT EXISTS products(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),name text NOT NULL,price_cents integer NOT NULL CHECK(price_cents>=0),available integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS business_settings(business_id text PRIMARY KEY REFERENCES businesses(id),description text NOT NULL DEFAULT '',contact text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',latitude real NOT NULL DEFAULT 38.7223,longitude real NOT NULL DEFAULT -9.1393,is_open integer NOT NULL DEFAULT 1,slot_capacity integer NOT NULL DEFAULT 5,retention_days integer NOT NULL DEFAULT 90,logo text NOT NULL DEFAULT '',secondary_color text NOT NULL DEFAULT '#283820',appearance text NOT NULL DEFAULT 'light',location_updated_at integer,location_source text NOT NULL DEFAULT 'manual',gps_updated_at integer,accent_color text NOT NULL DEFAULT '#f0a76d',social_links text NOT NULL DEFAULT '',cover text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS inventory(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),name text NOT NULL,unit text NOT NULL DEFAULT 'un',quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity),minimum integer NOT NULL DEFAULT 5,supplier text NOT NULL DEFAULT '',UNIQUE(business_id,name));
CREATE TABLE IF NOT EXISTS recipes(product_id text NOT NULL REFERENCES products(id),inventory_id text NOT NULL REFERENCES inventory(id),quantity integer NOT NULL CHECK(quantity>0),PRIMARY KEY(product_id,inventory_id));
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),request_hash text NOT NULL UNIQUE,customer_name text NOT NULL,contact text NOT NULL,total_cents integer NOT NULL,status text NOT NULL DEFAULT 'pending',payment text NOT NULL DEFAULT 'unpaid',created_at integer NOT NULL,pickup_at integer,event_id text,location_snapshot text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS orders_business_date ON orders(business_id,created_at);
CREATE TABLE IF NOT EXISTS order_items(order_id text NOT NULL REFERENCES orders(id),product_id text NOT NULL,name text NOT NULL,quantity integer NOT NULL,unit_cents integer NOT NULL,customization text NOT NULL DEFAULT '',category text NOT NULL DEFAULT 'Menu',PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS stock_movements(id text PRIMARY KEY,inventory_id text NOT NULL REFERENCES inventory(id),delta integer NOT NULL,reason text NOT NULL,order_id text,created_at integer NOT NULL);
CREATE TABLE IF NOT EXISTS reservations(order_id text NOT NULL REFERENCES orders(id),inventory_id text NOT NULL REFERENCES inventory(id),quantity integer NOT NULL,state text NOT NULL DEFAULT 'reserved',PRIMARY KEY(order_id,inventory_id));
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),title text NOT NULL,address text NOT NULL,starts_at integer NOT NULL,ends_at integer NOT NULL,is_public integer NOT NULL DEFAULT 1,type text NOT NULL DEFAULT 'market');
CREATE TABLE IF NOT EXISTS product_details(product_id text PRIMARY KEY REFERENCES products(id),category text NOT NULL DEFAULT 'Menu',description text NOT NULL DEFAULT '',allergens text NOT NULL DEFAULT '',image text NOT NULL DEFAULT '',extra_name text NOT NULL DEFAULT '',extra_cents integer NOT NULL DEFAULT 0,prep_minutes integer NOT NULL DEFAULT 15,extra_inventory_id text REFERENCES inventory(id),variant_name text NOT NULL DEFAULT '',variant_cents integer NOT NULL DEFAULT 0,promotion_cents integer,ingredients text NOT NULL DEFAULT '',tags text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),user_id text,action text NOT NULL,created_at integer NOT NULL);
CREATE TABLE IF NOT EXISTS categories(business_id text NOT NULL REFERENCES businesses(id),name text NOT NULL,display_order integer NOT NULL DEFAULT 0,PRIMARY KEY(business_id,name));
CREATE TABLE IF NOT EXISTS event_products(event_id text NOT NULL REFERENCES events(id),product_id text NOT NULL REFERENCES products(id),PRIMARY KEY(event_id,product_id));
CREATE TABLE IF NOT EXISTS modifier_groups(id text PRIMARY KEY,product_id text NOT NULL REFERENCES products(id),name text NOT NULL,min_count integer NOT NULL DEFAULT 0,max_count integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS modifier_options(id text PRIMARY KEY,group_id text NOT NULL REFERENCES modifier_groups(id),name text NOT NULL,price_cents integer NOT NULL DEFAULT 0,inventory_id text REFERENCES inventory(id),quantity integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS saved_locations(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),name text NOT NULL,address text NOT NULL,latitude real NOT NULL,longitude real NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id text PRIMARY KEY,business_id text NOT NULL REFERENCES businesses(id),title text NOT NULL,done integer NOT NULL DEFAULT 0,assigned_to text REFERENCES users(id));
CREATE TABLE IF NOT EXISTS customer_notes(business_id text NOT NULL REFERENCES businesses(id),contact text NOT NULL,note text NOT NULL,PRIMARY KEY(business_id,contact));
CREATE TABLE IF NOT EXISTS password_resets(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),expires integer NOT NULL);
CREATE TABLE IF NOT EXISTS request_limits(key text PRIMARY KEY,count integer NOT NULL,expires integer NOT NULL);
